import Link from "next/link";
import type { Metadata } from "next";
import { MarketingHeader } from "@/components/marketing/MarketingHeader";
import { MarketingFooter } from "@/components/marketing/MarketingFooter";
import { Reveal } from "@/components/marketing/Reveal";
import { CtaBand } from "@/components/marketing/sections";
import { formatDate, readMinutes, APP_URL } from "@/lib/blog";
import { getHelpData, categorySlug } from "@/lib/help";
import type { BlogPost } from "@prisma/client";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Help center — guides, tutorials & docs",
  description:
    "Search the Nxeon help center for step-by-step guides on VPS hosting, game servers, domains, security, and control panels. Everything you need to run your servers.",
  alternates: { canonical: "/help" },
  openGraph: {
    type: "website",
    title: "Nxeon Help Center",
    description:
      "Searchable guides and tutorials on VPS hosting, game servers, domains, security, and more.",
    url: `${APP_URL}/help`,
  },
};

function matches(post: BlogPost, q: string): boolean {
  const hay = `${post.title} ${post.excerpt} ${post.category} ${(post.tags ?? []).join(" ")}`.toLowerCase();
  return hay.includes(q);
}

/** Compact article row used inside a category section and search results. */
function ArticleCard({ post }: { post: BlogPost }) {
  return (
    <Link
      href={`/blog/${post.slug}`}
      className="card card-hover group flex h-full items-start gap-4"
    >
      <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-white/[0.06] bg-gradient-to-br from-accent-blue/12 to-brand-500/12 text-2xl">
        <span>{post.coverEmoji ?? "📄"}</span>
      </div>
      <div className="min-w-0">
        <h3 className="text-sm font-semibold text-white transition-colors group-hover:text-brand-200">
          {post.title}
        </h3>
        <p className="mt-1 line-clamp-2 text-[13px] leading-relaxed text-slate-400">{post.excerpt}</p>
        <p className="mt-2 text-[11px] text-slate-500">{readMinutes(post.body)} min read</p>
      </div>
    </Link>
  );
}

export default async function HelpCenter({
  searchParams,
}: {
  searchParams: Promise<{ c?: string; q?: string }>;
}) {
  const sp = await searchParams;
  const query = (sp.q ?? "").trim().toLowerCase();
  const activeCat = (sp.c ?? "").trim().toLowerCase();

  const { sections, popular, total } = await getHelpData();

  // Determine which sections to render given the active category / search query.
  const filteredSections = sections
    .filter((s) => (activeCat ? categorySlug(s.category.name) === activeCat : true))
    .map((s) => ({
      ...s,
      posts: query ? s.posts.filter((p) => matches(p, query)) : s.posts,
    }))
    .filter((s) => s.posts.length > 0);

  const isFiltering = Boolean(query || activeCat);
  const resultCount = filteredSections.reduce((n, s) => n + s.posts.length, 0);

  return (
    <div className="flex min-h-screen flex-col">
      <MarketingHeader />
      <main className="flex-1">
        {/* Hero + search */}
        <section className="relative overflow-hidden">
          <div
            className="pointer-events-none absolute inset-x-0 top-0 h-[420px] opacity-70"
            style={{ backgroundImage: "radial-gradient(ellipse 60% 50% at 50% 0%, rgba(111,71,245,0.16), transparent)" }}
          />
          <div className="relative mx-auto max-w-4xl px-5 py-20 text-center sm:px-6">
            <Reveal>
              <p className="section-label mb-3">Help center</p>
              <h1 className="text-4xl font-extrabold tracking-tight sm:text-5xl">
                How can we <span className="grad-text">help you</span>?
              </h1>
              <p className="mx-auto mt-5 max-w-2xl text-lg text-slate-400">
                Search {total} guides and tutorials, or browse by topic. Everything you need to
                deploy, secure, and scale your servers.
              </p>
              <form method="GET" action="/help" className="mx-auto mt-8 flex max-w-xl gap-2">
                <input
                  type="search"
                  name="q"
                  defaultValue={sp.q ?? ""}
                  placeholder="Search the knowledge base…"
                  aria-label="Search help articles"
                  className="input flex-1"
                  autoComplete="off"
                />
                <button type="submit" className="btn-primary px-5">
                  Search
                </button>
              </form>
            </Reveal>
          </div>
        </section>

        <section className="mx-auto max-w-6xl px-5 pb-24 sm:px-6">
          {/* Category grid — hidden while actively searching to keep results front-and-centre */}
          {!query && (
            <div className="mb-14">
              <div className="mb-5 flex items-center justify-between">
                <h2 className="text-lg font-semibold text-white">Browse by topic</h2>
                {activeCat && (
                  <Link href="/help" className="text-sm font-medium text-brand-300 hover:text-brand-200">
                    ← All topics
                  </Link>
                )}
              </div>
              <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                {sections.map((s, i) => {
                  const slug = categorySlug(s.category.name);
                  const active = slug === activeCat;
                  return (
                    <Reveal key={slug} delay={(i % 3) * 50}>
                      <Link
                        href={active ? "/help" : `/help?c=${slug}`}
                        className={`card card-hover group flex h-full items-start gap-4 ${
                          active ? "border-brand-500/50 ring-1 ring-brand-500/30" : ""
                        }`}
                      >
                        <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl border border-white/[0.06] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 text-2xl">
                          <span>{s.category.emoji}</span>
                        </div>
                        <div className="min-w-0">
                          <div className="flex items-center gap-2">
                            <h3 className="text-base font-semibold text-white transition-colors group-hover:text-brand-200">
                              {s.category.name}
                            </h3>
                            <span className="rounded-full border border-white/10 bg-white/[0.05] px-2 py-0.5 text-[11px] font-medium text-slate-400">
                              {s.posts.length}
                            </span>
                          </div>
                          <p className="mt-1 text-[13px] leading-relaxed text-slate-400">
                            {s.category.blurb}
                          </p>
                        </div>
                      </Link>
                    </Reveal>
                  );
                })}
              </div>
            </div>
          )}

          {/* Popular articles — only on the unfiltered landing view */}
          {!isFiltering && popular.length > 0 && (
            <div className="mb-14">
              <h2 className="mb-5 text-lg font-semibold text-white">Popular articles</h2>
              <div className="grid gap-4 sm:grid-cols-2">
                {popular.map((post, i) => (
                  <Reveal key={post.id} delay={(i % 2) * 60}>
                    <ArticleCard post={post} />
                  </Reveal>
                ))}
              </div>
            </div>
          )}

          {/* Search / filter result heading */}
          {isFiltering && (
            <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
              <p className="text-sm text-slate-400">
                {resultCount === 0 ? "No results" : `${resultCount} article${resultCount === 1 ? "" : "s"}`}
                {query && (
                  <>
                    {" "}for <span className="font-medium text-white">“{sp.q}”</span>
                  </>
                )}
              </p>
              <Link href="/help" className="text-sm font-medium text-brand-300 hover:text-brand-200">
                Clear
              </Link>
            </div>
          )}

          {/* Sections */}
          {filteredSections.length === 0 ? (
            <div className="card py-16 text-center">
              <p className="text-lg font-semibold text-white">Nothing found</p>
              <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
                Try a different search term or browse the topics above. Still stuck? Our team is one
                ticket away.
              </p>
              <div className="mt-6 flex justify-center gap-3">
                <Link href="/help" className="btn-secondary px-5">
                  Browse all topics
                </Link>
                <Link href="/dashboard/support" className="btn-primary px-5">
                  Contact support
                </Link>
              </div>
            </div>
          ) : (
            <div className="space-y-12">
              {filteredSections.map((s) => {
                const slug = categorySlug(s.category.name);
                return (
                  <div key={slug} id={slug}>
                    <div className="mb-5 flex items-center gap-3">
                      <span className="text-2xl">{s.category.emoji}</span>
                      <div>
                        <h2 className="text-xl font-bold tracking-tight text-white">{s.category.name}</h2>
                        <p className="text-[13px] text-slate-400">{s.category.blurb}</p>
                      </div>
                    </div>
                    <div className="grid gap-4 sm:grid-cols-2">
                      {s.posts.map((post) => (
                        <ArticleCard key={post.id} post={post} />
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          <div className="mt-20">
            <CtaBand />
          </div>
        </section>
      </main>
      <MarketingFooter />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";

/**
 * Bottom cookie-consent banner. Records the visitor's choice in the
 * `nxeon_cookie_consent` cookie (value "all" or "necessary") for one year and
 * hides itself once a choice exists — on this visit and on every reload.
 *
 * Mounted once in the root layout by the orchestrator. It renders nothing on
 * the server (and nothing until mounted) to avoid a hydration flash, then
 * appears only when no prior consent cookie is present.
 */

const COOKIE = "nxeon_cookie_consent";
const ONE_YEAR = 60 * 60 * 24 * 365;

function hasConsent(): boolean {
  if (typeof document === "undefined") return true;
  return document.cookie.split("; ").some((c) => c.startsWith(`${COOKIE}=`));
}

function setConsent(value: "all" | "necessary") {
  document.cookie = `${COOKIE}=${value}; path=/; max-age=${ONE_YEAR}; SameSite=Lax`;
}

export default function CookieConsent() {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    if (!hasConsent()) setVisible(true);
  }, []);

  if (!visible) return null;

  function choose(value: "all" | "necessary") {
    try {
      setConsent(value);
    } catch {
      /* cookies blocked — hide anyway so we don't nag */
    }
    setVisible(false);
  }

  return (
    <div
      role="dialog"
      aria-modal="false"
      aria-label="Cookie consent"
      className="fixed inset-x-0 bottom-0 z-[60] px-4 pb-4 sm:px-6 sm:pb-6"
    >
      <div className="mx-auto flex max-w-3xl flex-col gap-4 rounded-2xl border border-white/[0.1] bg-navy-850/95 p-5 shadow-2xl backdrop-blur-md sm:flex-row sm:items-center sm:gap-6">
        <div className="min-w-0 flex-1">
          <p className="text-sm font-semibold text-white">We value your privacy</p>
          <p className="mt-1 text-[13px] leading-relaxed text-slate-400">
            We use cookies to keep you signed in and to understand how the site is used. You can
            accept all cookies or stick to only the ones we need to run.{" "}
            <Link
              href="/legal/privacy"
              className="font-medium text-brand-300 underline decoration-brand-300/40 underline-offset-2 hover:text-brand-200"
            >
              Privacy policy
            </Link>
            .
          </p>
        </div>
        <div className="flex shrink-0 gap-2">
          <button
            type="button"
            onClick={() => choose("necessary")}
            className="btn-secondary px-4 py-2 text-sm"
          >
            Necessary only
          </button>
          <button
            type="button"
            onClick={() => choose("all")}
            className="btn-primary px-4 py-2 text-sm"
          >
            Accept all
          </button>
        </div>
      </div>
    </div>
  );
}

"use server";

