/**
 * Persist the user's dismissal of the getting-started card for one year.
 * Called by the client card's dismiss button.
 */
export async function dismissOnboarding(): Promise<{ ok: true }> {
  await requireUser();
  const jar = await cookies();
  jar.set(ONBOARDING_COOKIE, "1", {
    path: "/",
    maxAge: 60 * 60 * 24 * 365,
    sameSite: "lax",
  });
  return { ok: true };
}

