"use client";

import { useEffect, useState, useTransition } from "react";
import Link from "next/link";
import { dismissOnboarding } from "@/lib/actions-onboarding";

/**
 * "Getting started" checklist for new customers, mounted on the dashboard by
 * the orchestrator: `<OnboardingChecklist steps={await getOnboardingSteps()} />`.
 *
 * Steps are computed server-side (see lib/actions-onboarding.ts) and passed in.
 * The card:
 *   - hides itself once every step is complete,
 *   - hides once dismissed (persisted in the `nxeon_onboarding_done` cookie,
 *     read client-side on mount and written both here and by the server action),
 *   - renders nothing until mounted to avoid a hydration flash.
 */

export const ONBOARDING_COOKIE = "nxeon_onboarding_done";

export type OnboardingStep = {
  key: "server" | "funds" | "twofa" | "domain";
  label: string;
  desc: string;
  done: boolean;
  href: string;
  cta: string;
};

function isDismissed(): boolean {
  if (typeof document === "undefined") return true;
  return document.cookie.split("; ").some((c) => c.startsWith(`${ONBOARDING_COOKIE}=`));
}

export default function OnboardingChecklist({ steps }: { steps: OnboardingStep[] }) {
  const [hidden, setHidden] = useState(true);
  const [pending, startTransition] = useTransition();

  useEffect(() => {
    setHidden(isDismissed());
  }, []);

  const doneCount = steps.filter((s) => s.done).length;
  const allDone = doneCount === steps.length;

  // Nothing to show: dismissed, or the customer has finished every step.
  if (hidden || allDone || steps.length === 0) return null;

  function dismiss() {
    // Hide instantly and persist client-side; also fire the server action so
    // the choice survives even if this cookie is later cleared client-side.
    try {
      document.cookie = `${ONBOARDING_COOKIE}=1; path=/; max-age=${60 * 60 * 24 * 365}; SameSite=Lax`;
    } catch {
      /* non-fatal */
    }
    setHidden(true);
    startTransition(() => {
      void dismissOnboarding().catch(() => {});
    });
  }

  const pct = Math.round((doneCount / steps.length) * 100);
  const next = steps.find((s) => !s.done);

  return (
    <div className="card relative overflow-hidden">
      <div
        className="pointer-events-none absolute inset-0 opacity-60"
        style={{
          backgroundImage:
            "radial-gradient(ellipse 50% 80% at 100% 0%, rgba(138,112,251,0.12), transparent)",
        }}
      />
      <div className="relative">
        <div className="flex items-start justify-between gap-4">
          <div>
            <h2 className="text-base font-semibold text-white">Getting started</h2>
            <p className="mt-1 text-[13px] text-slate-400">
              Finish setting up your account — {doneCount} of {steps.length} done.
            </p>
          </div>
          <button
            type="button"
            onClick={dismiss}
            disabled={pending}
            aria-label="Dismiss getting started checklist"
            className="btn-ghost -mr-1 -mt-1 shrink-0 px-2 py-1 text-xs text-slate-400 hover:text-white disabled:opacity-50"
          >
            Dismiss
          </button>
        </div>

        {/* Progress bar */}
        <div className="mt-4 h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
          <div
            className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 transition-all duration-500"
            style={{ width: `${pct}%` }}
          />
        </div>

        {/* Steps */}
        <ul className="mt-5 space-y-2">
          {steps.map((step) => {
            const isNext = next?.key === step.key;
            return (
              <li
                key={step.key}
                className={`flex items-center gap-3 rounded-xl border p-3 ${
                  step.done
                    ? "border-white/[0.06] bg-white/[0.02]"
                    : isNext
                      ? "border-brand-500/40 bg-brand-500/[0.06]"
                      : "border-white/[0.06]"
                }`}
              >
                <span
                  className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border ${
                    step.done
                      ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-400"
                      : "border-white/10 bg-white/[0.04] text-slate-500"
                  }`}
                  aria-hidden
                >
                  {step.done ? (
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
                      <path d="M20 6 9 17l-5-5" />
                    </svg>
                  ) : (
                    <span className="h-1.5 w-1.5 rounded-full bg-current" />
                  )}
                </span>
                <div className="min-w-0 flex-1">
                  <p className={`text-sm font-medium ${step.done ? "text-slate-400 line-through" : "text-white"}`}>
                    {step.label}
                  </p>
                  {!step.done && <p className="text-[12px] text-slate-500">{step.desc}</p>}
                </div>
                {!step.done && (
                  <Link
                    href={step.href}
                    className={`shrink-0 px-3 py-1.5 text-xs ${isNext ? "btn-primary" : "btn-secondary"}`}
                  >
                    {step.cta}
                  </Link>
                )}
                {step.done && (
                  <span className="shrink-0 text-[11px] font-medium text-emerald-400">Done</span>
                )}
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

